  metaTitle: 'The Complete Marketing Analytics Guide',
  metaDescription: 'Introduction: What business decisions should marketing analytics improve? Marketing teams rarely lack data.',
  excerpt: 'Introduction: What business decisions should marketing analytics improve? Marketing teams rarely lack data. They lack a dependable way to turn data into decisions.',
  category: 'growth',
